	writeCopilotSession(t, base, "other", "/work/elsewhere", 5*24*time.Hour, now)
	writeCopilotSession(t, base, "old", repoRoot, 60*24*time.Hour, now)

	got, err := copilotImporter{}.Discover(repoRoot, base, now, nil)
